INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(2901, 'Leviticus 10:9', 'Leviticus', 10, 9, '&nbsp;”د ميو يا د شرابو څښلو نه پس تۀ او ستا زامن زما د حضور مقدسې خېمې ته مۀ راځئ، کۀ تاسو داسې وکړل، نو مړۀ به شئ. دا قانون د همېشه دپاره دے چې ستاسو ټول اولاد به پرې عمل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2902, 'Leviticus 10:10', 'Leviticus', 10, 10, '&nbsp;تاسو خامخا د هغه څيزونو په مينځ کښې فرق کوئ څۀ چې د خُدائ پاک دى يا څۀ چې د عام استعمال دپاره دى او د هغه څيزونو په مينځ کښې چې کوم پاک دى او کوم ناپاک دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2903, 'Leviticus 10:11', 'Leviticus', 10, 11, '&nbsp;تاسو بنى اِسرائيلو ته هغه ټول قانون وښايئ کوم چې ما د موسىٰ په ذريعه درکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2904, 'Leviticus 10:12', 'Leviticus', 10, 12, '&nbsp;موسىٰ هارون او د هغۀ دوه پاتې شوو زامنو، اِلى‌عزر او اِتمر ته وفرمائيل، ”د غلې هغه نذرانه واخلئ کومه چې مالِک خُدائ ته په اور سوزېدونکې نذرانې نه پاتې شوې ده، پتيره روټۍ د دې سره پخه کړئ او د قربان‌ګاه په خوا کښې يې وخورئ، ځکه چې دا نذرانه ډېره مقدسه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2905, 'Leviticus 10:13', 'Leviticus', 10, 13, '&nbsp;دا په مقدس ځائ کښې وخورئ، دا مالِک خُدائ ته په اور سوزېدونکې نذرانه کښې ستا او ستا د زامنو حِصه ده. دا هغه څۀ دى چې مالِک خُدائ ما ته حُکم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2906, 'Leviticus 10:14', 'Leviticus', 10, 14, '&nbsp;خو تاسو او ستاسو خاندان هغه سينه او پتُون خوړلے شئ کوم چې د اِمامانو دپاره مالِک خُدائ ته د خاص تُحفې او خاص برخې په توګه پېش کيږى. دا تاسو په يو پاک ځائ کښې خوړلے شئ. دا نذرانې تاسو او ستاسو بچو له د بنى اِسرائيلو د سلامتۍ د نذرانو د برخې نه درکړے شوې دى چې ستاسو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2907, 'Leviticus 10:15', 'Leviticus', 10, 15, '&nbsp;هغه پتُون او سينه به په هغه وخت راوړے شى چې کله وازګه په اور سوزېدونکې نذرانې په توګه مالِک خُدائ ته پېش کيږى. دا برخې به همېشه دپاره ستاسو او ستاسو د بچو وى، هم هغه شان چې څنګه مالِک خُدائ حُکم کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2908, 'Leviticus 10:16', 'Leviticus', 10, 16, '&nbsp;موسىٰ د ګناه نذرانې د چېلى په حقله تپوس وکړو او خبر شو چې هغه خو سوزولے شوے دے. په دې باندې هغه اِلى‌عزر او اِتمر ته په قهر شو او پوښتنه يې وکړه چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2909, 'Leviticus 10:17', 'Leviticus', 10, 17, '&nbsp;”د ګناه نذرانه تاسو په مقدس ځائ کښې ولې ونۀ خوړله؟ دا ډېره مقدسه ده او دا مالِک خُدائ تاسو له د دې دپاره درکړې ده چې د کفارې ادا کولو په ذريعه د مالِک خُدائ په نظر کښې د قوم ګناهونه لرې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2910, 'Leviticus 10:18', 'Leviticus', 10, 18, '&nbsp;چې د دې وينه مقدسې خېمې ته وړلے شوې نۀ وې، نو تاسو له په کار وُو چې هغه قربانى مو هلته خوړلے، چې څنګه ما حُکم درکړے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2911, 'Leviticus 10:19', 'Leviticus', 10, 19, '&nbsp;هارون په جواب کښې وفرمائيل، ”کۀ ما د ګناه نذرانه خوړلې وے، نو مالِک خُدائ به قبوله کړې وے څۀ؟ خلقو نن په خپله د ګناه نذرانه مالِک خُدائ ته پېش کړه او هغوئ خپله سوزېدونکې نذرانه هم راوړه، خو بيا هم دا مصيبتونه ما ته راپېښ شول.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2912, 'Leviticus 10:20', 'Leviticus', 10, 20, '&nbsp;چې کله موسىٰ دا واورېدل، نو د هغۀ تسلى وشوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2913, 'Leviticus 11:1', 'Leviticus', 11, 1, '&nbsp;مالِک خُدائ موسىٰ او هارون ته دا اصُول وښودل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2914, 'Leviticus 11:2', 'Leviticus', 11, 2, '&nbsp;کوم چې د بنى اِسرائيلو دپاره وُو. تاسو په زمکه ګرځېدونکے هر هغه ځناور خوړلے شئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2915, 'Leviticus 11:3', 'Leviticus', 11, 3, '&nbsp;چې د هغې د پښو سومونه په مينځ بېل وى او بيا بيا شخوند وهى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2916, 'Leviticus 11:7', 'Leviticus', 11, 7, '&nbsp;خنزير مۀ خورئ. دا به خامخا ناپاک ګڼلے شى، د دې د پښو نوکونه په مينځ بېل وى، خو بيا بيا شخوند نۀ وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2917, 'Leviticus 11:8', 'Leviticus', 11, 8, '&nbsp;دا ځناور مۀ خورئ يا چې مړۀ وى نو لاس به هم نۀ وروړئ، دا ناپاک دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2918, 'Leviticus 11:9', 'Leviticus', 11, 9, '&nbsp;تاسو هغه هر قِسم کبان خوړلے شئ کوم چې وزر او په څرمن پترى لرى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2919, 'Leviticus 11:10', 'Leviticus', 11, 10, '&nbsp;خو داسې د اوبو بل هر يو څيز چې وزر او په څرمن پترى نۀ لرى هغه نۀ شئ خوړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2920, 'Leviticus 11:11', 'Leviticus', 11, 11, '&nbsp;داسې څيزونه به ستاسو دپاره حرام وى. تاسو به هيڅکله هم د دې غوښه نۀ خورئ يا کۀ مړۀ وى نو لاس به هم نۀ وروړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2921, 'Leviticus 11:12', 'Leviticus', 11, 12, '&nbsp;تاسو هر هغه څيز مۀ خورئ کوم چې په اوبو کښې اوسيږى او وزر او په څرمن پترى نۀ لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2922, 'Leviticus 11:20', 'Leviticus', 11, 20, '&nbsp;الوتونکى حشرات ناپاک دى، تاسو د دې نه کرکه وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2923, 'Leviticus 11:21', 'Leviticus', 11, 21, '&nbsp;خو بغېر د هغې نه چې په پښو ګرځى او ټوپونه وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2924, 'Leviticus 11:22', 'Leviticus', 11, 22, '&nbsp;تاسو کېرړى، د قحطۍ مُلخان او نور مُلخان خوړلے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2925, 'Leviticus 11:23', 'Leviticus', 11, 23, '&nbsp;خو نور ټول واړۀ څيزونه چې وزر لرى او په زمکه باندې په پښو ګرځى دا به ستاسو دپاره حرام وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2926, 'Leviticus 11:31', 'Leviticus', 11, 31, '&nbsp;دا ستاسو دپاره ناپاک دى. چې دا مړۀ وى او هر څوک چې لاس وروړى نو هغه به تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2927, 'Leviticus 11:32', 'Leviticus', 11, 32, '&nbsp;او يا کۀ دا مړۀ وى او په څۀ څيز باندې وغورزيږى، نو هغه به ناپاک وى. هغه څيز کۀ د لرګى نه جوړ وى، کپړه، څرمن، يا بوجۍ وى، کۀ هر څيز دپاره هم استعماليږى. هغه څيز به په اوبو کښې غوپه کړے شى، خو دا به بيا هم تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2928, 'Leviticus 11:33', 'Leviticus', 11, 33, '&nbsp;کۀ دا مړۀ شوى ځناور د خاورو په لوښى کښې وغورزيږى، په هغې کښې چې هر څۀ وى نو هغه به ناپاک وى، نو تاسو هغه لوښے مات کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2929, 'Leviticus 11:34', 'Leviticus', 11, 34, '&nbsp;هر هغه خوراک کوم چې په عامه توګه خوړلے شى، خو کۀ په دې خوراک باندې د هغه لوښى نه اوبۀ توئ کړے شوې وى، نو هغه خوراک به ناپاک وى او په داسې لوښى کښې چې د څښلو څۀ هم وى نو هغه به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2930, 'Leviticus 11:35', 'Leviticus', 11, 35, '&nbsp;کۀ دا مړۀ شوى ځناور په هر څۀ باندې راوغورزيږى نو هغه به ناپاک وى، کۀ هغه د خټې نغرے وى يا د پخلى لوښے وى نو ماتولے به شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2931, 'Leviticus 11:36', 'Leviticus', 11, 36, '&nbsp;خو چينه يا ډيګۍ به پاکه وى، خو کۀ بل هر څوک دې مړو ځناورو له لاس وروړى نو هغه به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2932, 'Leviticus 11:37', 'Leviticus', 11, 37, '&nbsp;کۀ دا په هغه تخم باندې وغورزيږى کوم چې کَرلے کيږى، نو تخم به پاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2933, 'Leviticus 11:38', 'Leviticus', 11, 38, '&nbsp;خو کۀ تخم په اوبو کښې پستولے شى او دا قِسم مړ ځناور ورباندې راوغورزيږى، نو تخم به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2934, 'Leviticus 11:39', 'Leviticus', 11, 39, '&nbsp;کۀ يو حلال ځناور مړ شى، کۀ هر څوک ورله لاس وروړى نو هغه به تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2935, 'Leviticus 11:40', 'Leviticus', 11, 40, '&nbsp;کۀ هر څوک د دې ځناور څۀ غوښه وخورى، نو هغه به خامخا خپلې جامې وينځى، خو هغه به بيا هم تر ماښامه پورې ناپاک وى، هر څوک چې دا مړۀ ځناور يوسى نو هغه به خامخا خپلې جامې ووينځى، خو هغه به بيا هم تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2936, 'Leviticus 11:41', 'Leviticus', 11, 41, '&nbsp;تاسو هغه ټول ځناور مۀ خورئ کوم چې په زمکه باندې ګرځى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2937, 'Leviticus 11:42', 'Leviticus', 11, 42, '&nbsp;لکه چې په خېټه باندې، يا په څلورو پښو باندې او يا په ډېرو پښو ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2938, 'Leviticus 11:43', 'Leviticus', 11, 43, '&nbsp;د دې په خوړلو باندې خپل ځانونه مۀ ناپاکه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2939, 'Leviticus 11:44', 'Leviticus', 11, 44, '&nbsp;زۀ مالِک خُدائ ستاسو خُدائ پاک يم او تاسو خپل ځانونه پاک او مقدس ساتئ، ځکه چې زۀ مقدس يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2940, 'Leviticus 11:45', 'Leviticus', 11, 45, '&nbsp;زۀ مالِک خُدائ يم چا چې تاسو د مِصر مُلک نه راوويستلئ چې زۀ ستاسو خُدائ پاک يم، تاسو خامخا مقدس اوسئ، ځکه چې زۀ مقدس يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2941, 'Leviticus 11:46', 'Leviticus', 11, 46, '&nbsp;نو دا د ځناورو او مارغانو په حقله قانون دے، د هغه هر ژوندى څيز په حقله چې په اوبو کښې اوسيږى او چې په زمکه ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2942, 'Leviticus 11:47', 'Leviticus', 11, 47, '&nbsp;چې تاسو د پاک او ناپاک او د حلال او حرام په مينځ کښې فرق وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2943, 'Leviticus 12:1', 'Leviticus', 12, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته دا اصُول وښودل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2944, 'Leviticus 12:2', 'Leviticus', 12, 2, '&nbsp;کوم چې د بنى اِسرائيلو دپاره دى. د يو زوئ پېدا کېدو نه پس ښځه تر اووۀ ورځو پورې ناپاکه وى، هم هغه شان چې څنګه د مياشتنۍ بيمارۍ په دوران کښې ناپاکه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2945, 'Leviticus 12:3', 'Leviticus', 12, 3, '&nbsp;په اتمه ورځ به ماشوم سنت کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2946, 'Leviticus 12:4', 'Leviticus', 12, 4, '&nbsp;نو ښځه دې درې دېرش ورځې نور هم انتظار کوى، ترڅو چې هغه پاکه شى. نو په دې دوران کښې به هغه هيڅ پاک څيز له لاس نۀ وروړى او نۀ به مقدسې خېمې ته ورننوځى چې تر څو پورې هغه پاکه شوې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2947, 'Leviticus 12:5', 'Leviticus', 12, 5, '&nbsp;د يوې لور پېدا کېدو نه پس ښځه تر څوارلسو ورځو پورې هم هغه شان ناپاکه وى، چې څنګه د مياشتنۍ بيمارۍ په دوران کښې ناپاکه وى. او د پوره پاکېدو دپاره به هغه شپږ شپېتۀ ورځې نور هم انتظار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2948, 'Leviticus 12:6', 'Leviticus', 12, 6, '&nbsp;چې کله د هغې د ناپاکوالى وخت ختم شى نو هغه پاکه شى، کۀ د هغې زوئ يا لور پېدا شوې وى، نو هغه به اِمام ته د مالِک خُدائ د حضور مقدسې خېمې خولې ته د يو کال ګډُورے د سوزېدونکې نذرانې دپاره او يوه کونتره يا يوه ګوګوشتکه د ګناه د نذرانې دپاره راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2949, 'Leviticus 12:7', 'Leviticus', 12, 7, '&nbsp;اِمام به د هغې نذرانه مالِک خُدائ ته پېش کړى او د هغې د ناپاکۍ د لرې کولو دپاره به کفاره ادا کړى او د وينې د بهېدو نه به هغه پاکه شى. دا هغه اصُول دى چې يوه ښځه به يې د هلک يا د جينۍ د پېدا کېدو نه پس ضرور کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
