(2951, 'Leviticus 13:1', 'Leviticus', 13, 1, '&nbsp;بيا مالِک خُدائ موسىٰ او هارون ته دا اصُول وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
