(2992, 'Leviticus 13:44', 'Leviticus', 13, 44, '&nbsp;نو اِمام به اِعلان وکړى چې هغه ناپاک دے، ځکه چې د هغۀ په سر باندې د جذام بيمارى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2993, 'Leviticus 13:45', 'Leviticus', 13, 45, '&nbsp;د کوم کس چې د جذام بيمارى وى نو هغه به خامخا شلېدلې جامې اغوندى، خپل وېښتۀ به ببر پرېږدى، خولۀ او پوزه دې پټه کړى او چغې دې وهى، ”زۀ ناپاک يم، زۀ ناپاک يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2994, 'Leviticus 13:46', 'Leviticus', 13, 46, '&nbsp;چې تر کومې پورې د هغۀ دا بيمارى وى نو هغه به ناپاک وى او هغه به د خېمو نه بهر، د نورو نه لرې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2995, 'Leviticus 13:49', 'Leviticus', 13, 49, '&nbsp;کۀ دا پشم شين بخن يا سور بخن وى، دا يو خورېدونکے پشم دے او دا به خامخا اِمام ته ښودلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2996, 'Leviticus 13:50', 'Leviticus', 13, 50, '&nbsp;اِمام به يې وګورى او هغه څيز به تر اووۀ ورځو پورې جدا کېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2997, 'Leviticus 13:51', 'Leviticus', 13, 51, '&nbsp;هغه به دا په اوومه ورځ بيا وګورى او کۀ پشم پرې خور شوے وى، نو هغه څيز ناپاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2998, 'Leviticus 13:52', 'Leviticus', 13, 52, '&nbsp;اِمام به دا وسوزوى، ځکه چې دا يو خورېدونکے پشم دے کوم چې به خامخا په اور ختمولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2999, 'Leviticus 13:53', 'Leviticus', 13, 53, '&nbsp;خو، کۀ هغه دا وګورى او اِمام ته پته ولګى چې پشم په هغه څيز باندې خور شوے نۀ دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3000, 'Leviticus 13:54', 'Leviticus', 13, 54, '&nbsp;هغه به حُکم وکړى چې دا دې ووينځلے شى او د نورو اووۀ ورځو دپاره دې جدا وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');